with lines as (select id, customer_id, created_at, attr_key, attr_value from carts lateral view outer explode(attributes) li as attr_key, attr_value) select attr_key, count(distinct id) as distinct_ids, count(*) filter (where attr_key = 'gift') as gift_rows, count_if(attr_key = 'weight_kg') as weight_kg_events, sort_array(collect_set(attr_key)) as attr_key_list, size(collect_set(attr_key)) as num_attr_keys from lines group by attr_key order by num_attr_keys desc;
